using System.Text;
using System.Text.Json;
internal static class LibraryAlternateSourceTests{
 internal static async Task Run(){
  var temp=Path.Combine(Path.GetTempPath(),"LibrarySourceAccept-"+Guid.NewGuid().ToString("N"));var h=new SimAssemblyHeader("01PART                ","fixture","V1.2","PART                ","PART","A","202020","A",false);var store=new SimLibraryBomStore(temp,()=>[h]);var key=h.SourceKeyRaw;
  SimPersona P(params string[] rights)=>new("tester","tester","Fixture","ACTIVE",[],rights,false,"fixture");var both=P("assembly_library.view","assembly_library.edit","technical_review.disposition");var editor=P("assembly_library.view","assembly_library.edit");
  void Check(bool b,string label){if(!b)throw new Exception(label);}async Task Reject(Func<Task> action,string label){try{await action();}catch(Exception e)when(e is SimRfqIntakeProblem or LibraryBomPermissionException){return;}throw new Exception("Expected rejection: "+label);}
  var txt=string.Join('\t',SimVproParser.Headers)+"\tDRAW#=OTHER REV V*\n"+string.Join('\t',new[]{"001","CPN","Resistor","","1","1","EA","1","0","0","0","P",""})+"\n"+string.Join('\t',new[]{"002","MPN-ALT","Resistor","","10",".0001","EA","1","0","0","0","P",""})+"\n"+string.Join('\t',new[]{"003","","(18.1) R1","","0","0","","0","0","0","0","",""})+"\n";
  var bytes=Encoding.ASCII.GetBytes(txt);var v=await store.Get(key,both);v=await store.Change(new(key,v.Token,"START"),both);v=await store.Change(new(key,v.Token,"IMPORT",TextBase64:Convert.ToBase64String(bytes),FileName:"fixture.txt",ConfirmIdentity:true,IdentityReason:"Fixture source applies"),both);var row=v.Record.Draft!.Rows.Single();var alt=row.Alternates.Single();
  Check(alt.Status=="PROPOSED"&&alt.Decision is null,"import not approval");await Reject(async()=>await store.Change(new(key,v.Token,"ALTERNATE",RowId:row.Id,AlternateId:alt.Id,AlternateDecision:"APPROVE_SOURCE"),editor),"edit not approval right");
  var clean=v.Record;v=await store.Change(new(key,v.Token,"ALTERNATE",RowId:row.Id,AlternateId:alt.Id,AlternateDecision:"APPROVE_SOURCE"),both);var accepted=v.Record.Draft!.Rows.Single().Alternates.Single();Check(accepted.Status=="APPROVED"&&accepted.Decision!.Id==both.Id&&accepted.Reason is null&&accepted.SourceDecision!.SourceHash==v.Record.Draft.EvidenceHash,"factual source evidence and attribution without fabricated reason");Check(v.Record.Draft.Rows.Single().SelectedAlternateId is null,"accept separate from select");Check(v.Record.Draft.Rows.Single().IdentityBasis=="UNRESOLVED"&&accepted.Manufacturer=="","no invented primary classification or manufacturer");Check((await new SimLibraryBomStore(temp,()=>[h]).Get(key,both)).Record.Draft!.Rows[0].Alternates[0].SourceDecision is not null,"decision persists");
  var saved=v.Record;var path=Path.Combine(temp,"assembly-library-v1",SimLibraryBomStore.Hash(Encoding.UTF8.GetBytes(key))+".json");async Task Fixture(LibraryBomRecord r)=>await File.WriteAllTextAsync(path,JsonSerializer.Serialize(r,SimLibraryBomStore.Json));
  // Each scenario is an isolated draft fixture, never a real Library record.
  foreach(var scenario in new[]{("CUSTOMER",true,true),("INTERNAL_UNKNOWN",true,true),("CUSTOMER",false,false),("UNRESOLVED",false,false),("MFG",true,false),("ASSEMBLY",true,false)}){
   var fixture=clean with{Draft=clean.Draft! with{Rows=[row with{IdentityBasis=scenario.Item1,IdentityConfirmed=scenario.Item2}]}};await Fixture(fixture);
   var result=await store.Change(new(key,SimLibraryBomStore.Token(fixture),"ALTERNATE",RowId:row.Id,AlternateId:alt.Id,AlternateDecision:"APPROVE_SOURCE"),both);
   Check((result.Record.Draft!.Rows[0].SelectedAlternateId==alt.Id)==scenario.Item3,"sole selection requires confirmed customer/internal identity");Check(result.Record.Draft.Rows[0].Acceptance is null,"whole row remains unaccepted");
   Check((await new SimLibraryBomStore(temp,()=>[h]).Get(key,both)).Record.Draft!.Rows[0].SelectedAlternateId==result.Record.Draft.Rows[0].SelectedAlternateId,"selection persists on reopen");
   var token=result.Token;await Reject(async()=>await store.Change(new(key,SimLibraryBomStore.Token(fixture),"ALTERNATE",RowId:row.Id,AlternateId:alt.Id,AlternateDecision:"APPROVE_SOURCE"),both),"stale acceptance cannot overwrite selection");Check((await store.Get(key,both)).Token==token,"failed acceptance writes nothing");
  }
  foreach(var testRow in new[]{row with{IdentityBasis="CUSTOMER",IdentityConfirmed=true,Alternates=[alt,new("second","OTHER","","PROPOSED")]},row with{IdentityBasis="CUSTOMER",IdentityConfirmed=true,ManufacturerPartNumber="OTHER-PRIMARY"},row with{IdentityBasis="CUSTOMER",IdentityConfirmed=true,SelectedAlternateId="different-existing"}}){var fixture=clean with{Draft=clean.Draft! with{Rows=[testRow]}};await Fixture(fixture);var result=await store.Change(new(key,SimLibraryBomStore.Token(fixture),"ALTERNATE",RowId:row.Id,AlternateId:alt.Id,AlternateDecision:"APPROVE_SOURCE"),both);Check(result.Record.Draft!.Rows[0].SelectedAlternateId!=alt.Id,"multiple or conflicting primary prevents shortcut");}
  var prior=alt with{Status="APPROVED",Decision=new("fixture","Fixture",DateTimeOffset.UtcNow)};
  var existing=clean with{Draft=clean.Draft! with{Rows=[row with{IdentityBasis="CUSTOMER",IdentityConfirmed=true,Alternates=[alt,prior with{Id="existing",PartNumber="EXISTING"}],SelectedAlternateId="existing"}]}};await Fixture(existing);var unchanged=await store.Change(new(key,SimLibraryBomStore.Token(existing),"ALTERNATE",RowId:row.Id,AlternateId:alt.Id,AlternateDecision:"APPROVE_SOURCE"),both);Check(unchanged.Record.Draft!.Rows[0].SelectedAlternateId=="existing","different approved selection retained");
  // Pending primary selection and neighboring edits are one atomic decision transaction.
  LibraryRowEdit E(LibraryBomRow x)=>new(x.Id,x.Find,x.SourcePartNumber,x.Description,x.Quantity,x.Unit,x.ReferenceDesignators,x.IdentityBasis,x.ManufacturerPartNumber,x.ManufacturerName,x.IdentityConfirmed,x.Dnp,x.Notes,x.PreparationRequired,x.SelectedAlternateId);
  var first=alt with{Id="first-approved",PartNumber=alt.PartNumber,Status="APPROVED",Decision=new("fixture","Fixture",DateTimeOffset.UtcNow)};
  var neighbor=row with{Id="neighbor",Find="2",Source=null,Alternates=[],Notes="original"};
  var atomic=clean with{Draft=clean.Draft! with{Rows=[row with{Alternates=[first,alt]},neighbor]}};await Fixture(atomic);
  var pendingRows=new[]{E(atomic.Draft.Rows[0]) with{SelectedAlternateId=first.Id},E(neighbor) with{Notes="neighbor pending edit"}};
  var command=new LibraryBomCommand(key,SimLibraryBomStore.Token(atomic),"ALTERNATE",DrawingRevision:atomic.Draft.DrawingRevision,BomRevision:atomic.Draft.BomRevision,QuantityBasis:"PER_ASSEMBLY",Rows:pendingRows,RowId:row.Id,AlternateId:alt.Id,AlternateDecision:"APPROVE_SOURCE");
  await Reject(async()=>await store.Change(command,editor),"atomic approval permission");Check((await store.Get(key,both)).Token==command.ExpectedToken,"permission failure saves neither edits nor decision");
  await Reject(async()=>await store.Change(command with{ExpectedToken="stale"},both),"atomic concurrency");
  await Reject(async()=>await store.Change(command with{Rows=[pendingRows[0] with{SourcePartNumber="changed"},pendingRows[1]]},both),"atomic source mismatch");Check((await store.Get(key,both)).Record.Draft!.Rows[1].Notes=="original","failed source check preserves neighboring saved state");
  var committed=await store.Change(command,both);var committedRow=committed.Record.Draft!.Rows[0];Check(committedRow.Alternates.All(a=>a.Status=="APPROVED")&&committedRow.Alternates[0].Decision!.Id=="fixture","correct ID approved even when numbers overlap; first decision retained");Check(committedRow.SelectedAlternateId==first.Id&&committed.Record.Draft.Rows[1].Notes=="neighbor pending edit","pending primary and neighboring edits persist atomically");Check(committedRow.Acceptance is null,"no whole-row acceptance");var reopened=await new SimLibraryBomStore(temp,()=>[h]).Get(key,both);Check(reopened.Token==committed.Token&&reopened.Record.Draft!.Rows[0].Alternates[1].Decision!.Id==both.Id,"second alternate persists after reopen");
  foreach(var d in new[]{clean.Draft! with{BomRevision="B"},clean.Draft! with{AssemblyNumber="OTHER"},clean.Draft! with{Import=clean.Draft.Import! with{VproImport=clean.Draft.Import.VproImport with{IdentityConfirmation=null}}},clean.Draft! with{Rows=[row with{Find="99"}]},clean.Draft! with{Rows=[row with{SourcePartNumber="OTHER"}]},clean.Draft! with{Rows=[row with{Alternates=[alt with{Status="STALE"}]}]},clean.Draft! with{Rows=[row with{Alternates=[alt with{PartNumber="FORGED"}]}]}}){var fixture=clean with{Draft=d};await Fixture(fixture);await Reject(async()=>await store.Change(new(key,SimLibraryBomStore.Token(fixture),"ALTERNATE",RowId:row.Id,AlternateId:alt.Id,AlternateDecision:"APPROVE_SOURCE"),both),"mismatch or stale source identity");}
  await Fixture(clean);var evidence=Path.Combine(temp,"assembly-library-v1","evidence",clean.Draft!.EvidenceHash+".txt");await File.WriteAllTextAsync(evidence,"replaced");await Reject(async()=>await store.Change(new(key,SimLibraryBomStore.Token(clean),"ALTERNATE",RowId:row.Id,AlternateId:alt.Id,AlternateDecision:"APPROVE_SOURCE"),both),"changed bytes");await File.WriteAllBytesAsync(evidence,bytes);
  v=await store.Change(new(key,SimLibraryBomStore.Token(clean),"ALTERNATE",RowId:row.Id,AlternateDecision:"ADD",PartNumber:"MANUAL"),both);var manual=v.Record.Draft!.Rows[0].Alternates.Last();await Reject(async()=>await store.Change(new(key,v.Token,"ALTERNATE",RowId:row.Id,AlternateId:manual.Id,AlternateDecision:"APPROVE_SOURCE"),both),"manual cannot use source shortcut");await Reject(async()=>await store.Change(new(key,v.Token,"ALTERNATE",RowId:row.Id,AlternateId:manual.Id,AlternateDecision:"APPROVED"),both),"manual still needs reason");
  await Fixture(saved);v=await store.Get(key,both);var edit=new LibraryRowEdit(row.Id,row.Find,row.SourcePartNumber,row.Description,row.Quantity,row.Unit,row.ReferenceDesignators,row.IdentityBasis,"","",false,false,"",false,alt.Id);v=await store.Change(new(key,v.Token,"SAVE",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",PreparationAssessed:true,Rows:[edit]),both);v=await store.Change(new(key,v.Token,"SUBMIT"),both);await Reject(async()=>await store.Change(new(key,v.Token,"ALTERNATE",RowId:row.Id,AlternateId:alt.Id,AlternateDecision:"APPROVE_SOURCE"),both),"submitted frozen");v=await store.Change(new(key,v.Token,"APPROVE",ReviewId:v.Record.Reviews.Last().Id,Comments:"Fixture final review"),both,true);await Reject(async()=>await store.Change(new(key,v.Token,"ALTERNATE",RowId:row.Id,AlternateId:alt.Id,AlternateDecision:"APPROVE_SOURCE"),both),"approved frozen");
  Check(!JsonSerializer.Serialize(alt,SimLibraryBomStore.Json).Contains("sourceDecision"),"legacy snapshot serialization preserved");Console.WriteLine("PASS explicit VPRO source acceptance, factual hash/row/revision evidence, actor/time/reopen; no auto selection or invented identity; stale/mismatched/tampered source rejection; manual evidence unchanged; permissions and frozen versions.");
 }
}
